	if err != nil {
		return "", false, err
	}
	r, ok := obj["$id"]
	if !ok {
		return "", false, rt.Missing(name, path, "$id")
	}
	var id *string
	if err := json.Unmarshal(r, &id); err != nil {
		return "", false, jsonError(name, path+"$id", err)
	}
	if id == nil {
		return "", false, fmt.Errorf("%s: %s$id: null", name, path)
	}
	if r, ok = obj["$retired"]; !ok {
		return *id, false, nil
	}
	var retired bool
